"""Independent final-round judgments from operated rendered UI and frozen subreview evidence."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'rounds/r34/reports'
C={f['id']:f for f in json.loads((ROOT/'contract/user-features.json').read_text())['features']}
D={'round':'R34','evaluator':'/root/review_r31_r34','platforms':{},'feature_observations':{},'journey_observations':{},'findings':[]}
def ep(p,folder,*names):return [f'evidence/{p}/{folder}/{n}.json' for n in names]
def obs(fid,p,ev,reason,verified=(),partial=(),missing=(),status='partial'):
    a={}
    for state,keys in [('verified',verified),('partial',partial),('missing',missing)]:
        for key in keys:
            kind,n=key.split(':');assert int(n)<len(C[fid]['mustKeep'][kind]),(fid,key)
            a[key]={'status':state,'observation':reason}
    D['feature_observations'].setdefault(fid,{})[p]={'status':status,'reason':reason,'evidence':ev,'assertions':a}
def journey(jid,p,ev,reason,status='partial'):
    D['journey_observations'].setdefault(jid,{})[p]={'status':status,'reason':reason,'evidence':ev}
def finding(fid,title,observed,correction,ev):
    D['findings'].append({'id':fid,'title':title,'observed':observed,'correction':correction,'evidence':ev})
I=lambda p,*n:ep(p,'import',*n)
U=lambda p,*n:ep(p,'upload',*n)
R=lambda p,*n:ep(p,'recording',*n)
