    uev=U(p,*(['07-queue-details','08-paused','13-first-still-paused','19-retry-same-id','20-session-file-missing','22-wrong-files-rejected','23-original-reselected','25-central-received','26-central-actually-received','31-original-context-preserved','33-local-queue-removed','37-retained-original-after-removal','38-original-still-openable'] if p=='web' else ['02-queued','03-identity-context','04-paused','05-continued','06-failed','07-retried','08-after-browser-reload','10-wrong-file-rejected','12-submitting','13-received','14-received-review','16-removed','17-original-retained','18-original-opened']))
